1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	};
50	
51	// Percentages MUST go through this helper. Applying them as exact integer
52	// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
53	// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
54	// at the very end that drift becomes a whole extra G.
55	const addPercent = (amount: number, percent: number): number =>
56	  (amount * (100 + percent)) / 100;
57	
58	const quote = ({ items }: QuoteStep): StepResult => {
59	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
60	  const withFirstInsurance = addPercent(policyBase, FIRST_INSURANCE_PERCENT);
61	
62	  return { premium: Math.ceil(withFirstInsurance + PROCESSING_FEE) };
63	};
64	
65	export const runScenario = (scenario: Scenario): ScenarioResult => ({
66	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
67	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
68	});
